import {domainRegistrationPage,bindDomainRegistration} from './domain-registration.js?v=b71c264ce900';
import {services,navigation,pages,official} from './data.js';
import {verified,institutional} from './verified.js';
import {icon} from './icons.js';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sourceMap=verified.sourceMap;
const slugAliases={'website-as-a-service':'waas','learning-management':'lmaas',collaboration:'video-conferencing',infrastructure:'data-centre'};
for(const s of services){const v=verified.services.find(v=>v.slug===(slugAliases[s.slug]||s.slug));if(v){s.description=v.summary;s.sections=v.sections.map(v=>[v.title,v.body]);s.source=v.source;s.portal=v.portal;s.status=v.status;s.relatedSources=v.relatedSources||[]}else if(s.slug==='research-development'){s.source=sourceMap.research}}
const projectPages=verified.projects.map(p=>['/projects/'+p.slug,p.title]);
const news=verified.news.map((n,i)=>({...n,slug:['ict-maintenance','kgbv-infrastructure','project-manager-level-02','project-engineer-level-02'][i]})).sort((a,b)=>b.date.localeCompare(a.date));
const allPages=[...pages,...projectPages,...news.map(n=>['/news/'+n.slug,n.title]),['/events','Events & Workshops'],['/about/acts-rules','Acts & Rules']];
const path=location.pathname.replace(/\/$/,'')||'/';
const link=(url,label,cls='text-link')=>`<a class="${cls}" href="${e(url)}" ${/^https?:/.test(url)?'target="_blank" rel="noopener noreferrer"':''}>${label}${icon(/^https?:/.test(url)?'external':'arrow')}</a>`;
const button=(url,label,secondary=false)=>link(url,e(label),'button'+(secondary?' secondary':''));
const brand=()=>`<a class="brand" href="/" aria-label="ERNET India — Education and Research Network home"><img class="brand-logo" src="/assets/ernet-official-logo.png" width="300" height="132" alt="ERNET India — Education & Research Network"></a>`;

const sourceNote=(url,label='Official ERNET source')=>`<p class="source-note">Source: <a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(label)} ${icon('external')}</a><br>Information checked 24 October 2026. Refer to the official source for updates.</p>`;
const title=(heading,description,parent)=>`<section class="page-top"><div class="container"><div class="breadcrumb"><a href="/">Home</a>${icon('arrow')}${parent?`<a href="${parent[0]}">${e(parent[1])}</a>${icon('arrow')}`:''}<span>${e(heading)}</span></div><div class="page-title"><h1>${e(heading)}</h1><p>${e(description)}</p></div></div></section>`;
const sidebox=(s)=>`<aside><div class="sidebox tint"><div class="iconbox">${icon(s.icon||'globe')}</div><h3 style="margin-top:18px">${s.portal?'Access the official service':'Connect with ERNET'}</h3><p>${s.portal?'Registration, account access and service management are available through the official portal.':'Discuss your institution’s requirements with the official support team.'}</p>${button(s.portal||'/contact',s.portal?'Visit official portal':'Contact & support')}</div><div class="sidebox"><h3>Explore related information</h3><a class="side-link" href="/services">${icon('network')} All services</a><a class="side-link" href="/resources">${icon('file')} Guides & resources</a><a class="side-link" href="/projects">${icon('book')} Projects & initiatives</a><a class="side-link" href="/contact">${icon('phone')} Service helpdesk</a></div></aside>`;
const filters=(items,extra='')=>`<div class="filter-bar">${items.map((x,i)=>`<button class="filter ${i?'':'active'}" data-filter="${e(x)}" aria-pressed="${!i}">${e(x)}</button>`).join('')}${extra}</div>`;
const searchField=placeholder=>`<div class="filter-search"><input type="search" id="collection-search" placeholder="${e(placeholder)}" aria-label="${e(placeholder)}"></div>`;
const documentRow=d=>`<article class="document">${icon('file')}<div class="document-main"><h3>${e(d.title)}</h3><p>${e(d.type||'Official document')} ${d.year?'· '+e(d.year):''} · PDF</p></div>${link(d.url,'Open PDF')}</article>`;
const empty=(message='No matching results.')=>`<div class="empty">${icon('search')}<h3 style="margin-top:14px">${e(message)}</h3><p>Try another keyword or select a different category.</p><button class="button secondary" id="reset-filters">Reset filters</button></div>`;
function header(){return `<a href="#main" class="skip">Skip to main content</a><header><div class="container masthead">${brand()}<div class="ministry"><img class="state-emblem" src="/assets/state-emblem-india.svg" width="44" height="70" alt="State Emblem of India — Satyameva Jayate"><div><strong>Ministry of Electronics &<br>Information Technology</strong><br>Government of India</div></div><button class="mobile-toggle" aria-label="Open navigation" aria-controls="primary-navigation" aria-expanded="false">${icon('menu')}</button></div><nav class="main-nav" aria-label="Main navigation" id="primary-navigation"><div class="container nav-inner">${navigation.map(n=>`<div class="nav-item ${path===n.path||(n.path!=='/'&&path.startsWith(n.path+'/'))?'active':''}"><a href="${n.path}" ${path===n.path?'aria-current="page"':''}>${n.label}${n.children?icon('chevron'):''}</a>${n.children?`<div class="dropdown">${n.children.map(([t,p])=>`<a href="${p}">${e(t)}</a>`).join('')}</div>`:''}</div>`).join('')}<a href="/portals" class="portal-nav">${icon('users')} Service portals</a></div></nav></header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-grid"><div>${brand()}<p>Connecting education, enabling research.<br>Exploring the digital infrastructure behind India’s academic community.</p></div><div><h3>Quick Links</h3><ul>${[['About ERNET India','/about'],['Our Services','/services'],['Projects & Research','/projects'],['News & Events','/news'],['Careers','/careers'],['Contact Us','/contact']].map(([t,p])=>`<li><a href="${p}">${t}</a></li>`).join('')}</ul></div><div><h3>Information & Resources</h3><ul>${[['Annual Reports','/resources/annual-reports'],['Tenders','/tenders'],['RTI & Disclosures','/rti'],['Policies & Credits','/policies'],['Accessibility','/accessibility'],['Sitemap','/sitemap']].map(([t,p])=>`<li><a href="${p}">${t}</a></li>`).join('')}</ul></div><div><h3>Official Contact</h3><div class="footer-contact">${icon('pin')}<span>5th Floor, Block-I, A Wing<br>DMRC IT Park, Shastri Park<br>New Delhi – 110053</span></div><div class="footer-contact">${icon('phone')}<a href="tel:+911122170578">+91 11-22170578</a></div><div class="footer-contact">${icon('mail')}<a href="mailto:support@eis.ernet.in">support@eis.ernet.in</a></div></div></div><div class="footer-bottom"><span>Independent ERNET India website replica · Information verified 24 October 2026</span><span><a href="/policies#credits">Image credits</a> &nbsp; | &nbsp; <a href="/feedback">Feedback</a> &nbsp; | &nbsp; <a href="${official}/" target="_blank" rel="noopener noreferrer">Official website ↗</a></span></div></div><div class="bottom-line"></div></footer><button class="back-top" aria-label="Back to top">${icon('arrow')}</button>`}
function home(){const featured=['connectivity','domain-registration','website-as-a-service','campus-networking'].map(id=>services.find(s=>s.slug===id));return `<section class="hero"><img class="hero-bg" src="/assets/hero-south-block.jpg" alt="Sandstone architecture of South Block, New Delhi, under a blue sky" fetchpriority="high"><div class="container hero-content"><div class="eyebrow">Education. Research. Connected.</div><h1>Empowering India’s<br>Education & Research<br>Ecosystem</h1><p>Connecting academic communities through networks, digital services and shared knowledge.</p><div class="tricolour" aria-hidden="true"><i></i><i></i><i></i></div><div class="button-row">${button('/about','Discover ERNET')}${button('/services','Explore Our Services',true)}</div></div></section><div class="container features">${[['satellite','Academic Connectivity','Networks for education and research','orange'],['users','Research & Collaboration','Bringing institutional expertise together',''],['shield','Institutional Digital Services','Domains, websites and learning platforms',''],['pin','A National Mission','Supporting India’s academic community','green']].map(([i,t,s,c])=>`<div class="feature"><div class="iconbox ${c}">${icon(i)}</div><div><strong>${t}</strong><small>${s}</small></div></div>`).join('')}</div><section class="principles" aria-label="ERNET at a glance"><div class="container principles-inner">${[['building','Since 1986','A legacy of academic networking'],['globe','8 domain categories','Education & research domains'],['network','IPv4 + IPv6','Published dual-stack architecture'],['book','Education & Research','At the heart of the mission']].map(([i,t,s])=>`<div class="principle">${icon(i)}<div><strong>${t}</strong><small>${s}</small></div></div>`).join('')}</div></section><section class="section soft"><div class="container"><div class="section-head center"><h2>Our Key Services</h2><p>Digital infrastructure and expertise for education, research and innovation.</p></div><div class="cards">${featured.map((s,i)=>`<article class="card"><a href="/services/${s.slug}" tabindex="-1" aria-hidden="true"><img src="/assets/${['satellite.jpg','servers.jpg','education.jpg','network.jpg'][i]}" alt="" loading="lazy"></a><div class="card-body"><h3>${s.title}</h3><p>${e(s.short)}</p>${link('/services/'+s.slug,'Know More')}</div></article>`).join('')}</div><div style="text-align:center;margin-top:25px">${link('/services','Explore all services')}</div></div></section><section class="pathways"><div class="container"><h3>Supporting the Education & Research Community</h3><div class="pathway-row">${[['building','Universities','Higher education'],['book','Schools','Connected learning'],['network','Research Institutions','Shared knowledge'],['users','Colleges','Digital campuses'],['globe','Academic Networks','Connected communities']].map(([i,t,s])=>`<a href="/services" class="pathway">${icon(i)}<strong>${t}</strong><span>${s}</span></a>`).join('')}</div></div></section><section class="section soft"><div class="container"><div class="two-col"><div><div class="section-head"><div><h2>Ideas into Impact</h2><p>Explore ERNET’s documented institutional projects.</p></div></div><article class="feature-project"><img src="/assets/education.jpg" alt="Students collaborating around a laptop; illustrative educational photograph" loading="lazy"><div class="feature-project-content"><span class="tag">Education Technology</span><h3>Bringing classrooms closer.<br>Taking learning further.</h3><p>Discover the smart virtual classroom and tele-education projects documented by ERNET India.</p>${link('/projects/ner-classrooms','Explore the project')}</div></article></div><div><div class="section-head"><h2>News & Notices</h2>${link('/news','View All')}</div><div class="news-list">${news.slice(0,3).map(n=>newsRow(n)).join('')}</div></div></div><div class="gateway"><div><h3>Your institution’s next step starts here.</h3><p>Find domain registration, website services, learning platforms and support.</p></div>${button('/portals','Explore Service Portals')}</div></div></section><section class="section"><div class="container"><div class="section-head"><div><h2>Knowledge & Resources</h2><p>Official publications, guidelines and useful institutional information.</p></div>${link('/resources','All Resources')}</div><div class="detail-grid">${verified.resources.slice(0,1).concat(verified.resources.slice(4,5)).map(d=>`<article class="document" style="border:1px solid var(--line);border-radius:6px">${icon('file')}<div class="document-main"><span class="tag">${e(d.type)}</span><h3 style="margin-top:9px">${e(d.title)}</h3><p>Official publication · PDF</p></div>${link(d.url,'Open')}</article>`).join('')}</div></div></section>`}
function newsRow(n){const d=new Date(n.date+'T00:00:00Z');return `<article class="news-item"><div class="date-block"><strong>${d.getUTCDate()}</strong>${d.toLocaleString('en-GB',{month:'short',timeZone:'UTC'}).toUpperCase()} ${d.getUTCFullYear()}</div><div><span class="tag">${e(n.category)}</span><h3><a href="/news/${n.slug}" style="color:inherit">${e(n.title)}</a></h3>${link('/news/'+n.slug,'Read More')}</div></article>`}
function servicesPage(){return title('Our Services','Networking, digital services and institutional expertise for India’s education and research community.')+`<section class="content-section"><div class="container">${filters(['All services','Networking','Digital services','Education & research','Institutional support'],searchField('Find a service…'))}<div class="cards service-grid" id="collection"></div><div class="gateway"><div><h3>Looking for the right service?</h3><p>The official support team can help with your institution’s requirements.</p></div>${button('/contact','Contact ERNET')}</div></div></section>`}
function serviceDetail(s){return title(s.title,s.description,['/services','Services'])+`<section class="content-section"><div class="container content-layout"><article class="prose">${s.image?`<img class="about-visual" src="/assets/${s.image}" alt="Illustrative photograph for ${e(s.title)}">`:''}${s.status?`<span class="tag" style="margin-bottom:25px">${e(s.status)}</span>`:''}${s.sections.map(([h,p])=>`<section><h2>${e(h)}</h2><p>${e(p)}</p></section>`).join('')}${s.slug==='domain-registration'?domainExtras():''}${s.relatedSources?.length?`<h2>Guidance from the official service</h2><ul>${s.relatedSources.map(u=>`<li><a href="${e(u)}" target="_blank" rel="noopener noreferrer">${u.includes('tariff')?'Published tariff':u.includes('contact')?'Service helpdesk':'Supporting official information'} ↗</a></li>`).join('')}</ul>`:''}${sourceNote(s.source)}</article>${sidebox(s)}</div></section>`}
function domainExtras(){return `<div class="gateway"><div><h3>Prepare your domain application</h3><p>Check eligibility, choose a name and review the document checklist.</p></div>${button('/domain-registration','Start Preparation')}</div><h2>Reserved domain categories</h2><div class="filter-bar">${['ac.in','edu.in','res.in','school.in','alumni.in','विद्या.भारत','शिक्षा.भारत','शोध.भारत'].map(s=>`<span class="tag">${s}</span>`).join('')}</div><h2>Application journey</h2><ol><li>Review eligibility and the current domain guidelines.</li><li>Check the name using the official availability search.</li><li>Complete the institutional application and supporting documents.</li><li>Pay on the official portal and follow its verification process.</li><li>Use your official account to track, renew and manage the domain.</li></ol><div class="note">The official guidelines effective 25 August 2025 take precedence over older checklists. Confirm the applicable requirements before submitting.</div><div class="faq"><h2>Frequently asked questions</h2><details><summary>Can I register a domain on this website?</summary><p>Domain applications are submitted and managed on the official ERNET registry. This reference website provides guidance and links only.</p></details><details><summary>Where can I find current registration fees?</summary><p><a href="https://registry.ernet.in/tariff" target="_blank" rel="noopener noreferrer">Open the registry tariff</a> for category-specific charges, registration periods and taxes. The official invoice determines the amount payable.</p></details><details><summary>How do I get help with an existing domain?</summary><p>Email <a href="mailto:helpdesk@domain.ernet.in">helpdesk@domain.ernet.in</a> to open a ticket before calling 011-22170580 or 011-22170594. Published support hours are Monday–Friday, 9:30 AM–5:00 PM.</p></details></div>`}
function aboutPage(){const key=path.split('/')[2]||'about';const heading=allPages.find(([p])=>p===path)?.[1]||'About ERNET India';let content='';if(key==='about'){content=`<p class="intro">${e(verified.about.summary)}</p><img class="about-visual" src="/assets/hero-south-block.jpg" alt="South Block, New Delhi"><h2>Connecting institutions. Enabling discovery.</h2><p>From its beginnings as a national networking programme, ERNET has supported the academic community with network infrastructure, institutional digital services, technical expertise and capacity building.</p><div class="values"><div class="value">${icon('globe')}<h3>Our Vision</h3><p>${e(verified.about.vision)}</p></div><div class="value">${icon('shield')}<h3>Our Mission</h3><p>${e(verified.about.mission)}</p></div></div>${sourceNote(verified.about.visionMissionSource,'Citizen’s Charter — vision and mission')}`;}else if(key==='history'){content=verified.about.history.map(h=>`<section class="value" style="margin-bottom:20px"><span class="tag">${h.year}</span><h2>${h.title}</h2><p>${h.summary}</p>${link(h.source,'Official historical record')}</section>`).join('');}else if(key==='centres'){content=`<p class="intro">Published office locations and telephone numbers.</p>${verified.contact.offices.map(o=>`<section class="value" style="margin-bottom:20px"><h2>${e(o.name)}</h2><p>${e(o.address)}</p><a href="tel:${o.phone.replace(/[^+0-9]/g,'')}">${e(o.phone)}</a></section>`).join('')}`;}else{content=institutionBody(key)||({objectives:`<p class="intro">ERNET’s institutional mandate centres on the education and research community.</p><h2>Networks, knowledge and institutional capacity</h2><p>Its published objectives encompass networking and information infrastructure, research and development, technical services, training and collaboration.</p><div class="values">${[['network','Academic infrastructure','Support the communication needs of research and education.'],['book','Knowledge and skills','Develop expertise through ICT training and capacity building.'],['users','Institutional collaboration','Bring educational and research communities together.'],['spark','Research and innovation','Explore networking technologies and applications.']].map(([i,t,p])=>`<div class="value">${icon(i)}<h3>${t}</h3><p>${p}</p></div>`).join('')}</div>`,organization:`<p class="intro">ERNET India is an autonomous scientific society under MeitY.</p><h2>Governance and organization</h2><p>The official website publishes a Governing Council, Executive Committee, organizational chart and employee directory. Use the current official records for office holders and division responsibilities.</p>${institutionLinks([['Governing Council','governing-council'],['Executive Committee','executive-committee'],['Organization chart','organization'],['Employee directory','directory'],['Acts & Rules','acts-rules']])}`,'citizen-charter':`<p class="intro">The Citizen’s Charter sets out ERNET’s institutional purpose and approach to service.</p><h2>Vision</h2><p>${e(verified.about.vision)}</p><h2>Mission</h2><p>${e(verified.about.mission)}</p><h2>Service information</h2><p>Use the official charter for the full published commitments, responsibilities and service contacts.</p>`,'acts-rules':`<p class="intro">Published rules and administrative documents are available through ERNET’s official records.</p>${institutionLinks([['Acts and rules','acts-rules'],['RTI disclosures','rti-disclosures']])}`}[key]||'');}return title(heading,'An institution dedicated to connecting India’s education and research community.',['/about','About Us'])+`<section class="content-section"><div class="container"><nav class="about-tabs" aria-label="About ERNET">${navigation[1].children.map(([t,p])=>`<a class="filter ${path===p?'active':''}" href="${p}" ${path===p?'aria-current="page"':''}>${t}</a>`).join('')}</nav><div class="content-layout"><article class="prose">${content}${sourceNote(sourceMap[key]||verified.about.source)}</article>${sidebox({icon:'building'})}</div></div></section>`}
function institutionLinks(items){return `<div class="document-list">${items.map(([t,k])=>`<article class="document">${icon('file')}<div class="document-main"><h3>${t}</h3><p>Official ERNET information</p></div>${link(sourceMap[k], 'View')}</article>`).join('')}</div>`}
function institutionBody(key){const entry=Array.isArray(institutional)?institutional.find(x=>x.slug===key||x.key===key):institutional[key];if(!entry)return '';return `${entry.summary?`<p class="intro">${e(entry.summary)}</p>`:''}${(entry.sections||[]).map(s=>`<section><h2>${e(s.title)}</h2><p>${e(s.body)}</p></section>`).join('')}${entry.links?.length?`<ul>${entry.links.map(l=>`<li>${link(l.url,e(l.label))}</li>`).join('')}</ul>`:''}`}
function networkPage(){return title('Network Infrastructure','Academic networking that supports communication, collaboration and shared resources.')+`<section class="content-section"><div class="container content-layout"><article class="prose"><p class="intro">ERNET’s published network architecture combines terrestrial and satellite connectivity with an MPLS-enabled, IPv4 and IPv6 backbone.</p><img class="about-visual" src="/assets/network.jpg" alt="Blue optical fibres, illustrating network connectivity"><h2>A connected academic environment</h2><p>The official network description explains how ERNET’s points of presence connect across its backbone. It also describes the Bengaluru connection between the VSAT and terrestrial networks.</p><figure class="network-diagram"><div class="node core">${icon('network')} ERNET Academic Backbone</div><div class="line"></div><div class="node-row"><div class="node">${icon('globe')} Terrestrial network</div><div class="node">${icon('satellite')} VSAT network</div></div><div class="line"></div><div class="node">${icon('building')} Education & research institutions</div><figcaption>Conceptual relationship based on the published architecture. This is not a geographic map or live network status.</figcaption></figure><h2>Technology and institutional access</h2><p>The published portfolio includes MPLS VPN, dual-stack IP and multicast capabilities. Network availability, bandwidth and deployment conditions should be confirmed for each institutional requirement.</p><div class="values"><div class="value">${icon('wifi')}<h3>Campus networks</h3><p>Explore planning, design, campus Wi-Fi and institutional infrastructure.</p>${link('/services/campus-networking','Campus networking')}</div><div class="value">${icon('code')}<h3>IPv6</h3><p>Learn about published next-generation network capabilities and resources.</p>${link('/services/ipv6','Explore IPv6')}</div></div>${sourceNote(sourceMap.network)}</article>${sidebox({icon:'network'})}</div></section>`}
function projectsPage(research=false){return title(research?'Research & Development':'Projects & Initiatives',research?'Published research in networking, communications and emerging technologies.':'Explore documented programmes and deployments across education, research and institutional ICT.')+`<section class="content-section"><div class="container">${research?`<div class="prose"><p class="intro">ERNET’s published research overview covers computer networking, network management, wireless sensor networks, future Internet research and mobility in IP networks.</p>${institutionBody('research')}</div>`:''}${filters(['All projects','Education','Research','Infrastructure','Capacity building'],searchField('Search projects…'))}<p class="count">Project dates and statuses below describe published records, rather than a live programme tracker.</p><div class="detail-grid" id="collection"></div><div id="pagination" class="pagination"></div>${sourceNote(research?sourceMap.research:sourceMap['ongoing-projects'])}</div></section>`}
function projectGroup(p){return /classroom|school/i.test(p.slug)?'Education':/iot|lifi|optical|ipv6|6lowpan/i.test(p.slug)?'Research':/isea|work-based|wbl/i.test(p.slug)?'Capacity building':'Infrastructure'}
function projectDetail(p){return title(p.title,p.summary,['/projects','Projects'])+`<section class="content-section"><div class="container content-layout"><article class="prose"><span class="tag">${e(p.status)}</span><h2 style="margin-top:24px">Project overview</h2><p class="intro">${e(p.summary)}</p>${(p.sections?.length?[]:['objective','beneficiaries','organizations','technology','scope','dates','outcomes']).filter(k=>p[k]).map(k=>`<h2>${k.charAt(0).toUpperCase()+k.slice(1)}</h2><p>${e(Array.isArray(p[k])?p[k].join('; '):p[k])}</p>`).join('')}${(p.sections||[]).map(s=>`<h2>${e(s.title)}</h2><p>${e(s.body)}</p>`).join('')}<h2>Published project information</h2><p>The official project record provides the reported scope and institutional context. Historical deployments and published project periods should not be interpreted as current enrolment or ongoing service availability.</p>${button(p.source,'Read official project record')}${sourceNote(p.source)}<h2>Related services and resources</h2><div class="button-row">${button('/services/smart-classrooms','Educational technology',true)}${button('/resources','Publications & resources',true)}</div></article>${sidebox({icon:'book'})}</div></section>`}
function resourcesPage(){const annual=path.includes('annual-reports');return title(annual?'Annual Reports':'Publications & Resources',annual?'Published reports from ERNET’s official annual report archive.':'Official reports, registration guidance, forms and technical publications.')+`<section class="content-section"><div class="container">${filters(annual?['Annual report']:['All resources','Annual report','User guide','Form','Guideline','Technical resource','Governance'],searchField('Search publications…'))}<div class="filter-bar"><label style="margin:0;display:flex;align-items:center;gap:10px">Year<select id="year-filter" style="margin:0;min-width:140px"><option value="">All years</option>${[...new Set(verified.resources.map(d=>d.year).filter(Boolean))].sort().reverse().map(y=>`<option>${y}</option>`).join('')}</select></label></div><div class="document-list" id="collection"></div><div class="pagination" id="pagination"></div><p class="source-note">Documents open on the official source website. PDF links were checked on 24 October 2026; individual document contents have not been fully audited. Use the <a href="https://registry.ernet.in/guidelines" target="_blank" rel="noopener noreferrer">current registration guidelines</a> alongside downloadable application forms.</p></div></section>`}
function newsDirectory(){return `<div class="news-directory"><section class="news-directory-hero"><div class="news-hero-art" aria-hidden="true"><img src="/assets/campus.jpg" alt=""><svg viewBox="0 0 760 250" fill="none"><g stroke="#86bdeb" stroke-width="1" opacity=".75"><circle cx="300" cy="125" r="119"/><ellipse cx="300" cy="125" rx="53" ry="119"/><ellipse cx="300" cy="125" rx="93" ry="119"/><ellipse cx="300" cy="125" rx="119" ry="47"/><ellipse cx="300" cy="125" rx="109" ry="84"/><path d="M181 125h238M300 6v238M130 29l170 96L393 14l93 165-186-54 100 115L130 29 87 186l313 54M87 186l213-61 176-82M211 48l92 178 81-165-192 117 199 29"/></g><g fill="#1c89e6" stroke="#e9f7ff" stroke-width="2">${[[130,29],[300,125],[393,14],[486,179],[400,240],[87,186],[476,43],[211,48],[303,226],[384,61],[192,178],[391,207],[300,6]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4"/>`).join('')}</g><path d="M525 263C610 190 641 51 803 22" stroke="#ffb448" stroke-width="39"/><path d="M550 279C635 206 666 77 828 48" stroke="#fff" stroke-width="37"/><path d="M573 298C658 225 689 101 851 72" stroke="#20a969" stroke-width="38"/></svg></div><div class="container"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a>${icon('arrow')}<span aria-current="page">News & Events</span></nav><h1>News & Events</h1><p>Published notices and institutional updates from official ERNET sources.</p></div></section><section class="news-directory-content"><div class="container">${filters(['All notices','Careers','Tender','Events'],`<div class="filter-search">${icon('search')}<input type="search" id="collection-search" placeholder="Search notices…" aria-label="Search notices"></div>`)}<div class="news-snapshot"><span aria-hidden="true">i</span><p>Information snapshot: 24 October 2026. Always consult the official notice and amendments before acting.</p></div><div id="collection" class="news-notice-list"></div><div class="news-more"><div>${icon('book')}<div><h2>Explore events and workshops</h2><p>Browse documented training activities and official event resources.</p></div></div>${button('/events','Events & Workshops',true)}</div></div></section></div>`;}
function directoryNotice(n){const glyph=n.category==='Careers'&&n.title.includes('Manager')?`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v3M3 12c4 4 14 4 18 0M10 12h4v5h-4Z"/></svg>`:icon('file');return `<article class="notice-card ${n.category==='Tender'?'notice-tender':n.category==='Events'?'notice-event':'notice-career'}"><div class="notice-icon">${glyph}</div><div class="notice-copy"><div class="notice-meta"><span class="notice-tag">${e(n.category)}</span><span class="notice-divider" aria-hidden="true"></span><time datetime="${e(n.date)}">${e(n.date)}</time></div><h2><a href="/news/${n.slug}">${e(n.title)}</a></h2><p>${e(n.summary)}</p><p class="notice-status">${e(n.status)}</p>${link('/news/'+n.slug,'Read notice & documents')}</div></article>`;}
function tendersDirectory(){const years=[...new Set(news.filter(n=>n.category==='Tender').map(n=>n.date.slice(0,4)))].sort().reverse();const quick=(url,label,i)=>`<a href="${e(url)}" ${url.startsWith('http')?'target="_blank" rel="noopener noreferrer"':''}>${icon(i)}<span>${label}</span>${icon(url.startsWith('http')?'external':'arrow')}</a>`;return `<div class="tenders-directory"><section class="tenders-hero"><div class="tenders-hero-art" aria-hidden="true"><img src="/assets/campus.jpg" alt=""><svg viewBox="0 0 750 210" fill="none"><g stroke="#a2d3f1" stroke-width="1.2" opacity=".65"><path d="m60 140 90-101 152 118L222 20 60 140l242 17 91-117L150 39l296 145"/></g><g fill="#9bd7f8" opacity=".8">${[[60,140],[150,39],[302,157],[222,20],[393,40],[446,184]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4"/>`).join('')}</g><path d="M405 238C517 210 625 95 800 55" stroke="#ffac48" stroke-width="30"/><path d="M422 263C534 235 642 120 817 80" stroke="#fff" stroke-width="30"/><path d="M439 288C551 260 659 145 834 105" stroke="#28ae6a" stroke-width="30"/></svg></div><div class="container"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a>${icon('arrow')}<span aria-current="page">Tenders & Procurement</span></nav><h1>Tenders & Procurement</h1><p>Official procurement notices, published closing dates and amendments.</p></div></section><section class="tenders-content"><div class="container tenders-layout"><div class="tenders-main"><div class="tenders-toolbar"><div class="tender-tabs" aria-label="Tender status"><button type="button" class="active" data-tender-status="all" aria-pressed="true">All tenders</button><button type="button" data-tender-status="passed" aria-pressed="false">Closing date passed</button></div><div class="tender-search">${icon('search')}<input id="tender-search" type="search" placeholder="Search tenders…" aria-label="Search tenders"></div></div><div class="tenders-snapshot"><span aria-hidden="true">i</span><p>Information snapshot: 24 October 2026. Always consult the official notice and amendments before acting.</p></div><div id="tender-filter-summary" role="status" aria-live="polite"></div><div id="collection" class="tender-list" aria-live="polite"></div></div><aside class="tender-sidebar" aria-label="Tender filters and links"><section class="tender-side-card"><h2><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 4h18l-7 8v8l-4-2v-6Z"/></svg>Filter Tenders</h2><form id="tender-filter-form"><label for="tender-status">Tender Status</label><select id="tender-status" name="status"><option value="all">All tenders</option><option value="passed">Closing date passed</option></select><label for="tender-year">Year</label><select id="tender-year" name="year"><option value="">All years</option>${years.map(y=>`<option value="${y}">${y}</option>`).join('')}</select><div class="tender-filter-actions"><button type="submit" class="button">Apply Filters</button><button type="reset" class="button secondary">Reset</button></div></form></section><section class="tender-side-card tender-quicklinks"><h2>${icon('external')}Quick Links</h2><button type="button" id="tender-guidance-open">${icon('file')}<span>Procurement Guidelines</span>${icon('arrow')}</button>${quick('https://gem.gov.in/','GeM Portal','building')}${quick('/tenders?documents=amendments','Corrigenda & Amendments','file')}${quick(sourceMap['tender-archive'],'Archived Tenders','book')}${quick('/contact','Contact & Procurement Enquiries','phone')}</section></aside></div></section><dialog class="tender-guidance-dialog" id="tender-guidance" aria-labelledby="tender-guidance-title"><div class="tender-dialog-top"><h2 id="tender-guidance-title">Procurement guidance</h2><button type="button" id="tender-guidance-close" aria-label="Close procurement guidance">${icon('close')}</button></div><p>Use each official tender’s bid document for eligibility, submission requirements and published dates. Read its corrigenda and extensions together with the original document.</p><p>The dates shown here are from the published information snapshot. Check the official notice before acting.</p><div class="tender-guide-documents">${news.filter(n=>n.category==='Tender').map(n=>link('/news/'+n.slug,e(n.title))).join('')}${link('https://gem.gov.in/','Open the official GeM portal')}</div></dialog></div>`;}
function bindTenders(){const root=document.querySelector('.tenders-directory');if(!root)return;const items=news.filter(n=>n.category==='Tender'),form=root.querySelector('#tender-filter-form'),collection=root.querySelector('#collection'),search=root.querySelector('#tender-search'),statusSelect=root.querySelector('#tender-status'),yearSelect=root.querySelector('#tender-year'),summary=root.querySelector('#tender-filter-summary');let status='all',year='',query='',amendments=new URLSearchParams(location.search).get('documents')==='amendments';
const hasAmendment=n=>(n.documents||[]).some(d=>/corr|amend|extension/i.test(d.title+' '+d.url));
function renderTenders(){const found=items.filter(n=>(status==='all'||n.status==='Published closing date passed')&&(!year||n.date.startsWith(year+'-'))&&(!amendments||hasAmendment(n))&&`${n.title} ${n.summary} ${n.reference||''}`.toLowerCase().includes(query));root.querySelectorAll('[data-tender-status]').forEach(b=>{const active=b.dataset.tenderStatus===status;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});summary.innerHTML=amendments?`<div class="tender-applied"><span>Notices with corrigenda or amendments · ${found.length} result${found.length===1?'':'s'}</span><button type="button" id="tender-clear-amendments">Show all documents</button></div>`:(query||year||status!=='all'?`<p class="tender-result-count">${found.length} tender${found.length===1?'':'s'} found${year?' · '+e(year):''}</p>`:'');collection.innerHTML=found.length?found.map(n=>`<article class="tender-notice"><div class="tender-document-icon">${icon('file')}</div><div class="tender-notice-copy"><div class="tender-notice-meta"><span class="tender-label">Tender</span><span class="tender-meta-separator" aria-hidden="true"></span><time datetime="${e(n.date)}">${e(n.date)}</time><span class="tender-meta-separator" aria-hidden="true"></span><span class="tender-closed">${e(n.status==='Published closing date passed'?'Closing date passed':n.status)}</span></div><h2><a href="/news/${n.slug}">${e(n.title)}</a></h2><p>${e(n.summary)}</p>${link('/news/'+n.slug,'Read notice & documents')}</div></article>`).join(''):`<div class="tender-empty">${icon('search')}<h2>No matching tenders</h2><p>Try a different search or reset the filters.</p><button type="button" id="tender-empty-reset" class="button secondary">Reset filters</button></div>`;root.querySelector('#tender-empty-reset')?.addEventListener('click',reset);root.querySelector('#tender-clear-amendments')?.addEventListener('click',()=>{amendments=false;const url=new URL(location.href);url.searchParams.delete('documents');history.replaceState(null,'',url);renderTenders();search.focus();});}
function reset(){status='all';year='';query='';amendments=false;statusSelect.value='all';yearSelect.value='';search.value='';const url=new URL(location.href);url.searchParams.delete('documents');history.replaceState(null,'',url);renderTenders();}
root.querySelectorAll('[data-tender-status]').forEach(b=>b.addEventListener('click',()=>{status=b.dataset.tenderStatus;statusSelect.value=status;renderTenders();}));form.addEventListener('submit',ev=>{ev.preventDefault();status=statusSelect.value;year=yearSelect.value;renderTenders();});form.addEventListener('reset',ev=>{ev.preventDefault();reset();});search.addEventListener('input',()=>{query=search.value.trim().toLowerCase();renderTenders();});const dialog=root.querySelector('#tender-guidance');root.querySelector('#tender-guidance-open').addEventListener('click',()=>dialog.showModal());root.querySelector('#tender-guidance-close').addEventListener('click',()=>dialog.close());renderTenders();}
function newsPage(mode='all'){if(mode==='tenders')return tendersDirectory();if(mode==='all')return newsDirectory();const heading=mode==='tenders'?'Tenders & Procurement':mode==='careers'?'Careers & Recruitment':'News & Events';return title(heading,mode==='tenders'?'Official procurement notices, published closing dates and amendments.':mode==='careers'?'Published recruitment opportunities and their official application documents.':'Published notices and institutional updates from official ERNET sources.')+`<section class="content-section"><div class="container">${mode==='all'?filters(['All notices','Careers','Tender','Events'],searchField('Search notices…')):filters(mode==='tenders'?['All tenders','Closing date passed']:['All recruitment'],searchField('Search notices…'))}<div class="note">Information snapshot: 24 October 2026. Always consult the official notice and amendments before acting. ${mode==='tenders'?'The listed closing dates have passed.':mode==='careers'?'A website removal date is not an application deadline.':''}</div><div id="collection" class="news-list"></div><div class="gateway"><div><h3>${mode==='all'?'Explore events and workshops':'Looking for more notices?'}</h3><p>${mode==='all'?'Browse the documented training and event resources.':'The official archives contain additional published records.'}</p>${button(mode==='all'?'/events':sourceMap[mode==='tenders'?'tender-archive':'careers-archive'],mode==='all'?'Events & Workshops':'Official archive')}</div></div></section>`}
function newsDetail(n){return title(n.title,n.category+' · Published '+new Date(n.date+'T00:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}),['/news','News & Notices'])+`<section class="content-section"><div class="container content-layout"><article class="prose"><span class="tag">${e(n.category)}</span><h2 style="margin-top:24px">Notice information</h2><p>${e(n.summary)}</p><div class="table-wrap"><table><tbody><tr><th>Published</th><td>${e(n.date)}</td></tr>${n.reference?`<tr><th>Reference</th><td>${e(n.reference)}</td></tr>`:''}<tr><th>Status</th><td>${e(n.status)}</td></tr>${n.deadline?`<tr><th>Published closing date</th><td>${n.deadline} · date passed</td></tr>`:''}</tbody></table></div><h2>Official documents</h2><div class="document-list">${(n.documents||[]).map((d,i)=>documentRow({...d,title:n.documents.length===1?n.title:i===0&&n.category==='Careers'?'Recruitment notice':d.title,type:'Notice / amendment'})).join('')}</div><p class="source-note">Review the full official notice for eligibility, submission instructions and any amendments. This website does not accept applications or bids.</p>${button(n.source,'Open official notice')}${sourceNote(n.source)}</article>${sidebox({icon:'file'})}</div></section>`}
function contactPage(){return title('Contact Us','Find the right ERNET office or prepare an enquiry for the official support team.')+`<section class="content-section"><div class="container contact-grid"><form class="form-card" id="enquiry-form"><h2>Prepare an Enquiry</h2><p>Create a message to send using your email app. This website does not submit or store enquiries.</p><div class="form-row"><label>Full Name <span class="required">*</span><input name="name" autocomplete="name" maxlength="100" required placeholder="Enter your name"></label><label>Email Address <span class="required">*</span><input name="email" autocomplete="email" type="email" maxlength="180" required placeholder="you@institution.ac.in"></label></div><label>Institution / Organization<input name="organization" autocomplete="organization" maxlength="180" placeholder="Your institution’s name"></label><label>Enquiry Type <span class="required">*</span><select name="subject" required><option value="">Select an enquiry type</option><option>Domain registration & DNS</option><option>Website & LMS services</option><option>Web hosting</option><option>eduroam</option><option>Network & campus connectivity</option><option>General enquiry</option></select></label><label>Message <span class="required">*</span><textarea name="message" required minlength="10" maxlength="5000" placeholder="Tell us how the official support team can help…"></textarea></label><label class="consent"><input type="checkbox" required><span>I understand this prepares an email draft. I will review and send it myself.</span></label><button class="button" type="submit">Prepare Message ${icon('arrow')}</button><div id="form-status" role="status" aria-live="polite" tabindex="-1"></div></form><aside><div class="sidebox"><h3>Head Office</h3><div class="footer-contact">${icon('pin')}<span><strong>ERNET India</strong><br>${e(verified.contact.offices[0].address)}</span></div><div class="footer-contact">${icon('phone')}<a href="tel:+911122170578">+91 11-22170578</a></div><div class="footer-contact">${icon('mail')}<a href="mailto:support@eis.ernet.in">support@eis.ernet.in</a></div><div class="map-art"><div class="map-label">${icon('pin')}<span><strong>ERNET India</strong><br>DMRC IT Park · Shastri Park</span></div></div>${button('https://www.google.com/maps/search/?api=1&query=ERNET+India+DMRC+IT+Park+Shastri+Park+Delhi','Get Directions')}</div><div class="sidebox tint"><h3>Domain Registration Helpdesk</h3><p>Email to create a support ticket before calling.</p><div class="footer-contact">${icon('mail')}<a href="mailto:helpdesk@domain.ernet.in">helpdesk@domain.ernet.in</a></div><p>011-22170580 / 011-22170594<br>Monday–Friday · 9:30 AM–5:00 PM</p>${link('https://registry.ernet.in/contact-us','Official registry support')}</div>${link('/about/centres','Regional centres')}${sourceNote(sourceMap.contact)}</aside></div></section>`}
function portalIllustration(kind){const globe=`<g fill="none" stroke="#85b9ed" stroke-width="1"><circle cx="144" cy="100" r="73"/><ellipse cx="144" cy="100" rx="32" ry="73"/><ellipse cx="144" cy="100" rx="58" ry="73"/><ellipse cx="144" cy="100" rx="73" ry="29"/><ellipse cx="144" cy="100" rx="66" ry="53"/><path d="M71 100h146M144 27v146"/></g>`;const screens=`<g><rect x="84" y="56" width="128" height="91" rx="5" fill="#234c80"/><rect x="89" y="62" width="118" height="78" rx="2" fill="#fff"/><rect x="89" y="62" width="118" height="13" fill="#d6eaff"/><circle cx="95" cy="68" r="2" fill="#7fa8d8"/><path d="M105 68h28" stroke="#7fa8d8" stroke-width="3"/><rect x="99" y="85" width="98" height="30" rx="2" fill="#0a63d9"/><path d="m141 92 14 7-14 7Z" fill="#fff"/><path d="M100 124h41m9 0h45m-95 7h36m14 0h39" stroke="#b6cbe4" stroke-width="4"/><path d="M75 147h146l12 8H64Z" fill="#6087b8"/><rect x="57" y="89" width="56" height="69" rx="4" fill="#8fb4dd"/><rect x="61" y="94" width="48" height="59" rx="2" fill="#fff"/><rect x="66" y="101" width="38" height="17" fill="#cde3ff"/><path d="M66 125h32m-32 7h26m-26 7h31" stroke="#a6c8ef" stroke-width="3"/><circle cx="191" cy="44" r="24" fill="#fff" stroke="#b8d7f8"/><path d="m174 40 17-8 17 8-17 8Zm6 8v8l11 5 11-5v-8" fill="#075cf5"/></g>`;const wifi=`<g fill="none" stroke="#c5e2fb"><circle cx="147" cy="90" r="76" stroke-width="11"/><circle cx="147" cy="90" r="58" stroke-width="8"/><circle cx="147" cy="90" r="42" stroke-width="5"/></g><g fill="none" stroke="#0872df" stroke-width="7" stroke-linecap="round"><path d="M114 65a47 47 0 0 1 66 0M126 79a29 29 0 0 1 42 0M139 92a12 12 0 0 1 16 0"/></g><circle cx="147" cy="105" r="4" fill="#075cf5"/><text x="147" y="135" text-anchor="middle" fill="#103a6b" font-family="Arial,sans-serif" font-size="26" font-weight="700">eduroam</text><text x="147" y="157" text-anchor="middle" fill="#103a6b" font-family="Arial,sans-serif" font-size="19">India</text>`;const content=kind==='website'?screens:kind==='eduroam'?wifi:kind==='ipv6'?`${globe}<path d="M86 140V86m-7 9 7-10 7 10M205 121V67m-7 9 7-10 7 10" fill="none" stroke="#50a7ef" stroke-width="5"/><text x="151" y="120" text-anchor="middle" fill="#074eaa" font-family="Arial,sans-serif" font-size="43" font-weight="700">IPv6</text>`:`${globe}<rect x="68" y="85" width="142" height="34" rx="7" fill="#d0e3fb" opacity=".6"/><rect x="64" y="80" width="142" height="34" rx="5" fill="#fff" stroke="#b2d0f2"/><text x="76" y="102" fill="#0a499b" font-family="Arial,sans-serif" font-size="17" font-weight="700">www.</text><rect x="173" y="82" width="31" height="30" rx="4" fill="#075cf5"/><circle cx="186" cy="94" r="6" fill="none" stroke="#fff" stroke-width="2"/><path d="m190 99 6 6" stroke="#fff" stroke-width="2"/>`;return `<div class="portal-art portal-art-${kind}" aria-hidden="true"><img src="/assets/campus.jpg" alt="" loading="lazy"><svg viewBox="0 0 250 190" fill="none">${content}</svg></div>`;}
function portalsPage(){const portals=[
 {icon:'globe',title:'Domain Registration',tag:'Domain Services',art:'domain',text:'For eligible education and research institutions. Review guidelines and prepare your institutional domain application.',url:'/domain-registration',guide:'/services/domain-registration',guideText:'View guidelines',guideIcon:'file'},
 {icon:'monitor',title:'Website & Learning Services',tag:'Digital Services',art:'website',text:'WaaS and LMaaS for registered domain users. Explore templates, current tariffs and official service terms.',url:'https://registry.ernet.in/vas',guide:'/services/website-as-a-service',guideText:'Explore services',guideIcon:'network'},
 {icon:'wifi',title:'eduroam India',tag:'Academic Mobility',art:'eduroam',text:'Academic roaming information and institutional participation guidance through the official service.',url:'https://eduroam.ernet.in/',guide:'/services/eduroam',guideText:'Participation guide',guideIcon:'book'},
 {icon:'code',title:'IPv6 Resources',tag:'Networking Resources',art:'ipv6',text:'Official next-generation networking resources linked by ERNET India for education and research.',url:'https://ipv6.ernet.in/',guide:'/services/ipv6',guideText:'Technical resources',guideIcon:'file'}
 ];return `<div class="portal-page"><section class="portal-hero"><div class="portal-hero-art" aria-hidden="true"><img src="/assets/campus.jpg" alt=""><svg viewBox="0 0 620 210" fill="none"><g stroke="#81b9ed" opacity=".65"><circle cx="220" cy="105" r="100"/><ellipse cx="220" cy="105" rx="48" ry="100"/><ellipse cx="220" cy="105" rx="100" ry="42"/><path d="M120 105h200M220 5v200M82 38l139 67L302 25l81 112-162-32 88 87L82 38l-22 114 249 40M60 152l161-47 164-68"/></g><g fill="#1977dc">${[[82,38],[221,105],[302,25],[383,137],[309,192],[60,152],[385,37]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3"/>`).join('')}</g><path d="M418 75Q510 10 650-3" stroke="#ffaf56" stroke-width="17" opacity=".7"/><path d="M432 97Q530 34 650 23" stroke="#fff" stroke-width="17"/><path d="M445 119Q540 59 650 48" stroke="#74be8d" stroke-width="17" opacity=".8"/></svg></div><div class="container portal-hero-content"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a>${icon('arrow')}<span aria-current="page">Institutional Service Portals</span></nav><h1>Institutional Service Portals</h1><p>Choose the official platform for your institution’s next step.</p><div class="portal-motto" aria-hidden="true">Connecting<br>Education<br>Empowering<br>Research</div></div></section><section class="portal-content"><div class="container"><div class="portal-notice"><span class="portal-info" aria-hidden="true">i</span><p>Domain Registration opens a preparation workspace. Sign-in, applications, payments and records are handled on the official platforms.</p></div><div class="portal-grid">${portals.map(s=>`<article class="portal-card"><div class="portal-card-main"><div class="portal-service-icon">${icon(s.icon)}</div><div class="portal-copy"><span class="portal-tag">${s.tag}</span><h2>${s.title}</h2><p>${s.text}</p></div></div>${portalIllustration(s.art)}<div class="portal-card-actions">${button(s.url,'Continue to official portal')}<a class="portal-guide" href="${s.guide}">${icon(s.guideIcon)}<span>${s.guideText}</span>${icon('arrow')}</a></div></article>`).join('')}</div></div></section><section class="portal-help-band"><div class="container"><div class="portal-help"><div class="portal-help-heading">${icon('phone')}<div><h2>Need help?</h2><p>Find service documentation or get in touch with the support team.</p></div></div><a href="/resources">${icon('file')}<span>Service Documentation <br>& User Guides ${icon('arrow')}</span></a><a href="/domain-registration#dr-help">${icon('users')}<span>FAQs ${icon('arrow')}</span></a><a href="/contact">${icon('mail')}<span>Contact Support ${icon('arrow')}</span></a></div></div></section></div>`;}
function rtiPage(){return title('RTI & Public Information','Published institutional disclosures, governance documents and official information channels.')+`<section class="content-section"><div class="container content-layout"><article class="prose">${institutionBody('rti')||'<p class="intro">ERNET’s official website provides Right to Information resources and institutional disclosures.</p><h2>Access published information</h2><p>Refer to the official RTI page for the current designated officers, application procedure and institutional records.</p>'}${institutionLinks([['Right to Information','rti'],['Proactive disclosures','rti-disclosures'],['Acts and rules','acts-rules'],['Citizen’s Charter','citizen-charter'],['Web Information Manager','web-information-manager']])}<h2>Governance documents</h2><div class="document-list">${verified.resources.filter(d=>d.type==='Governance').map(documentRow).join('')}</div>${sourceNote(sourceMap.rti)}</article>${sidebox({icon:'file'})}</div></section>`}
function policiesPage(){return title('Website Policies & Credits','About this independent reference website and the sources behind it.')+`<section class="content-section"><div class="container content-layout"><article class="prose"><h2>Independent reference implementation</h2><p>This is an independently developed website replica for review and demonstration. It is not operated, authorized or endorsed by ERNET India or the Government of India. The ERNET name is used to identify the subject of this reference project.</p><h2>Content and external services</h2><p>Institutional information is summarized from the linked official sources. Content was checked on 24 October 2026. Service availability, fees, recruitment details and procurement conditions may change; official records take precedence.</p><h2>Privacy on this website</h2><p>Search and filters run in your browser. The enquiry form prepares a local email draft and does not send or store your message on a server. Text size and contrast preferences are stored only in your browser. The private hosting service may process access and request logs under its own policies.</p><h2>Official website policies</h2>${institutionLinks([['Privacy policy','privacy'],['Copyright policy','copyright'],['Hyperlink policy','hyperlink-policy'],['Disclaimer','disclaimer'],['Terms and conditions','terms'],['Security policy','security-policy']])}<h2 id="credits">Photography & design credits</h2><p>Hero photograph: <a href="https://commons.wikimedia.org/wiki/File:New_Delhi_government_block_03-2016_img4.jpg" target="_blank" rel="noopener noreferrer">A.Savin, Wikipedia</a>, licensed under the <a href="https://artlibre.org/licence/lal/en/" target="_blank" rel="noopener noreferrer">Free Art License</a>. The displayed composition crops and overlays the photograph.</p><div id="asset-credits"></div><p>Service photographs illustrate subject areas; they do not depict or certify ERNET facilities or partnerships. The ERNET logo is the original image from the <a href="https://ernet.in/sites/all/themes/ernet/logo.png" target="_blank" rel="noopener noreferrer">official ERNET website</a>, included at the user’s request in this private reference design. The State Emblem of India is shown in this private reference design at the user’s request, using public-domain artwork from <a href="https://commons.wikimedia.org/wiki/File:Emblem_of_India.svg" target="_blank" rel="noopener noreferrer">Wikimedia Commons</a>. Its display does not establish government affiliation or authorization. The ERNET artwork remains attributed to its owner; this reference design does not claim official authorization. Certification badges are not reproduced.</p><p>Typography: DM Sans and Manrope, self-hosted under the SIL Open Font License. <a href="/assets/dm-sans-LICENSE.txt" target="_blank" rel="noopener noreferrer">DM Sans license</a> · <a href="/assets/manrope-LICENSE.txt" target="_blank" rel="noopener noreferrer">Manrope license</a>.</p><h2>Accessibility</h2><p>The site includes keyboard navigation, visible focus states, text resizing, contrast controls, accessible forms and reduced-motion support. It does not claim government certification or a formal accessibility conformance audit.</p></article>${sidebox({icon:'shield'})}</div></section>`}
function accessibilityPage(){return title('Accessibility & Help','Use the website with your keyboard, screen reader and preferred display settings.')+`<section class="content-section"><div class="container prose"><h2>Navigation</h2><p>Use Tab and Shift+Tab to move between links and controls. Press Enter to open a link or activate a button. The first link skips directly to the main content. Navigation dropdown links are available through keyboard focus.</p><h2>Reading preferences</h2><p>Use the controls below to adjust text size and contrast. These preferences stay in your browser.</p><div class="button-row"><button class="button secondary" data-size="0.9" aria-label="Decrease text size">Smaller text</button><button class="button secondary" data-size="1" aria-label="Reset text size">Default text</button><button class="button secondary" data-size="1.12" aria-label="Increase text size">Larger text</button><button class="button secondary" id="contrast-toggle" aria-label="Toggle high contrast" aria-pressed="false">High contrast</button></div><h2>Documents and external sites</h2><p>Links with an external-link symbol open the official source in another tab. PDF accessibility depends on the published document. If a PDF cannot be read with your assistive software, request an accessible version through the official contact channel.</p><h2>Find information</h2><p>Search services, projects, notices and resources through the <a href="/search">site search</a>, or use the <a href="/sitemap">sitemap</a>. Collections include filters and clear empty states.</p>${button('/contact','Contact information')}${sourceNote(sourceMap.accessibility,'Official ERNET accessibility statement')}</div></section>`}
function feedbackPage(){return title('Feedback & Grievances','Use the appropriate official channel for institutional feedback and public enquiries.')+`<section class="content-section"><div class="container content-layout"><article class="prose"><h2>Feedback to ERNET India</h2><p>The official website provides a feedback page and a Web Information Manager contact. Use those channels for comments about ERNET’s services or official website.</p>${institutionLinks([['Official feedback page','feedback'],['Web Information Manager','web-information-manager'],['Service helpdesk','helpdesk'],['RTI and public information','rti']])}<h2>Service support</h2><p>For domain-related support, email helpdesk@domain.ernet.in to open a ticket before calling. For other service enquiries, consult the official helpdesk directory.</p>${button('/contact','Prepare an enquiry')}${sourceNote(sourceMap.feedback)}</article>${sidebox({icon:'mail'})}</div></section>`}
function eventsPage(){return title('Events & Workshops','Published technical learning, capacity-building and institutional event resources.')+`<section class="content-section"><div class="container content-layout"><article class="prose">${institutionBody('events')||'<h2>Technical learning and capacity building</h2><p>ERNET’s published training activities cover networking, ICT and voice/video conferencing. The ISEA Phase II project records historical information-security training for government officers.</p>'}<div class="note">Published historical events do not indicate current registration availability. Consult the official event pages for new announcements.</div><div class="button-row">${button('/services/training','Training & capacity building')}${button('/projects/isea','ISEA project',true)}</div>${sourceNote(sourceMap.training)}</article>${sidebox({icon:'users'})}</div></section>`}
function sitemapPage(){return title('Sitemap','Find your way through services, institutional information and resources.')+`<section class="content-section"><div class="container sitemap-grid">${[['Institutional information',allPages.filter(([p])=>p==='/'||p.startsWith('/about'))],['Services',allPages.filter(([p])=>p.startsWith('/services'))],['Projects & research',allPages.filter(([p])=>p.startsWith('/projects')||p==='/research')],['News, resources & support',allPages.filter(([p])=>!p.startsWith('/about')&&!p.startsWith('/services')&&!p.startsWith('/projects')&&p!=='/'&&p!=='/research')]].map(([t,arr])=>`<div class="sitemap-group"><h2>${t}</h2>${arr.map(([p,t])=>`<a href="${p}">${e(t)}</a>`).join('')}</div>`).join('')}</div></section>`}
function searchPage(){return title('Search ERNET India','Find services, projects, notices, publications and institutional information.')+`<section class="content-section"><div class="container"><form class="search-main" id="site-search" role="search"><input type="search" id="search-query" name="q" aria-label="Search site content" placeholder="What are you looking for?" value="${e(new URLSearchParams(location.search).get('q')||'')}"><button class="button">${icon('search')} Search</button></form><div id="search-status" class="count" role="status"></div><div id="search-results" class="search-results"></div></div></section>`}
function render(){document.body.classList.toggle('portal-view',path==='/portals');document.body.classList.toggle('news-view',path==='/news');document.body.classList.toggle('tenders-view',path==='/tenders');let body;if(path==='/')body=home();else if(path==='/domain-registration')body=domainRegistrationPage();else if(path==='/services')body=servicesPage();else if(path.startsWith('/services/')){const s=services.find(s=>path==='/services/'+s.slug);if(s)body=serviceDetail(s)}else if(path.startsWith('/about'))body=aboutPage();else if(path==='/network')body=networkPage();else if(path==='/projects'||path==='/research')body=projectsPage(path==='/research');else if(path.startsWith('/projects/')){const p=verified.projects.find(p=>path==='/projects/'+p.slug);if(p)body=projectDetail(p)}else if(path.startsWith('/resources'))body=resourcesPage();else if(path==='/news')body=newsPage();else if(path==='/tenders')body=newsPage('tenders');else if(path==='/careers')body=newsPage('careers');else if(path.startsWith('/news/')){const n=news.find(n=>path==='/news/'+n.slug);if(n)body=newsDetail(n)}else body=({'/contact':contactPage,'/portals':portalsPage,'/rti':rtiPage,'/policies':policiesPage,'/accessibility':accessibilityPage,'/feedback':feedbackPage,'/events':eventsPage,'/sitemap':sitemapPage,'/search':searchPage}[path])?.();if(!allPages.some(([p])=>p===path))body=null;if(!body)body=`<section class="error-page container"><div class="code">404</div><h1>Page not found</h1><p>The page may have moved. Explore the services or search the site.</p><div class="button-row" style="justify-content:center">${button('/','Go to Homepage')}${button('/search','Search Website',true)}</div></section>`;document.title=(allPages.find(([p])=>p===path)?.[1]||'Page not found')+' | ERNET India — Independent Reference';document.getElementById('app').innerHTML=header()+`<main id="main" tabindex="-1">${body}</main>`+footer();bindGlobal();if(path==='/tenders')bindTenders();else bindCollection();bindSearch();bindForm();if(path==='/domain-registration')bindDomainRegistration();if(path==='/policies')assetCredits();}
function bindGlobal(){const menu=document.querySelector('.mobile-toggle');menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',expanded);menu.setAttribute('aria-label',expanded?'Close navigation':'Open navigation');menu.innerHTML=icon(expanded?'close':'menu');document.querySelector('.main-nav').classList.toggle('open',expanded)});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){menu.click();menu.focus()}});document.querySelector('.back-top').addEventListener('click',()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));document.querySelectorAll('[data-size]').forEach(b=>b.addEventListener('click',()=>{document.documentElement.style.setProperty('--scale',b.dataset.size);try{localStorage.setItem('ernet-text-size',b.dataset.size)}catch{}}));let contrast=false;try{contrast=localStorage.getItem('ernet-contrast')==='true';const scale=localStorage.getItem('ernet-text-size');if(['0.9','1','1.12'].includes(scale))document.documentElement.style.setProperty('--scale',scale)}catch{}const c=document.getElementById('contrast-toggle');document.body.classList.toggle('contrast',contrast);c?.setAttribute('aria-pressed',contrast);c?.addEventListener('click',()=>{contrast=!contrast;document.body.classList.toggle('contrast',contrast);c.setAttribute('aria-pressed',contrast);try{localStorage.setItem('ernet-contrast',String(contrast))}catch{}});}
function bindCollection(){const el=document.getElementById('collection');if(!el)return;let category=document.querySelector('[data-filter].active')?.dataset.filter||'',q='',year='',page=1;const filterEls=[...document.querySelectorAll('[data-filter]')];const renderItems=()=>{let items,html;let size=6;if(path==='/services'){items=services.filter(s=>(category==='All services'||s.group===category)&&`${s.title} ${s.description} ${s.short}`.toLowerCase().includes(q));size=30;html=s=>`<article class="card service-card"><div class="iconbox">${icon(s.icon)}</div><span class="tag">${s.group}</span><h3>${s.title}</h3><p>${e(s.description)}</p>${link('/services/'+s.slug,'Know More')}</article>`}else if(path==='/projects'||path==='/research'){items=verified.projects.filter(p=>(category==='All projects'||projectGroup(p)===category)&&`${p.title} ${p.summary}`.toLowerCase().includes(q));html=p=>`<article class="detail-card"><span class="tag">${projectGroup(p)}</span><h3>${e(p.title)}</h3><p>${e(p.summary)}</p><p style="font-size:.68rem">${e(p.status)}</p>${link('/projects/'+p.slug,'Project details')}</article>`}else if(path.startsWith('/resources')){items=verified.resources.filter(d=>(category==='All resources'||d.type===category)&&(!year||d.year===year)&&`${d.title} ${d.type}`.toLowerCase().includes(q));html=documentRow}else{items=news.filter(n=>(path!=='/tenders'||n.category==='Tender')&&(path!=='/careers'||n.category==='Careers')&&(category.startsWith('All')||category==='Closing date passed'||category===n.category)&&`${n.title} ${n.summary} ${n.reference||''}`.toLowerCase().includes(q));size=20;html=n=>path==='/news'?directoryNotice(n):`<article class="news-item">${icon(n.category==='Tender'?'file':'users')}<div style="flex:1"><span class="tag">${n.category}</span><small style="margin-left:12px">${n.date}</small><h3><a href="/news/${n.slug}">${e(n.title)}</a></h3><p>${e(n.summary)}</p><p>${e(n.status)}</p>${link('/news/'+n.slug,'Read notice & documents')}</div></article>`}el.innerHTML=items.length?items.slice((page-1)*size,page*size).map(html).join(''):empty(category==='Events'?'No dated event notices in this collection.':'No matching results.');el.setAttribute('aria-live','polite');const pagination=document.getElementById('pagination');if(pagination){const count=Math.ceil(items.length/size);pagination.innerHTML=count>1?Array.from({length:count},(_,i)=>`<button data-page="${i+1}" class="${page===i+1?'active':''}" aria-label="Page ${i+1}" ${page===i+1?'aria-current="page"':''}>${i+1}</button>`).join(''):'';pagination.querySelectorAll('button').forEach(b=>b.onclick=()=>{page=Number(b.dataset.page);renderItems();el.scrollIntoView({block:'start',behavior:'auto'})})}document.getElementById('reset-filters')?.addEventListener('click',()=>{category=filterEls[0].dataset.filter;q='';year='';page=1;const search=document.getElementById('collection-search');if(search)search.value='';const y=document.getElementById('year-filter');if(y)y.value='';updateButtons();renderItems()})};function updateButtons(){filterEls.forEach(b=>{b.classList.toggle('active',b.dataset.filter===category);b.setAttribute('aria-pressed',b.dataset.filter===category)})}filterEls.forEach(b=>b.onclick=()=>{category=b.dataset.filter;page=1;updateButtons();renderItems()});document.getElementById('collection-search')?.addEventListener('input',ev=>{q=ev.target.value.trim().toLowerCase();page=1;renderItems()});document.getElementById('year-filter')?.addEventListener('change',ev=>{year=ev.target.value;page=1;renderItems()});renderItems()}
function bindSearch(){const form=document.getElementById('site-search');if(!form)return;const input=document.getElementById('search-query');const items=allPages.map(([url,title])=>({url,title,text:services.find(s=>url==='/services/'+s.slug)?.description||verified.projects.find(p=>url==='/projects/'+p.slug)?.summary||news.find(n=>url==='/news/'+n.slug)?.summary||'Institutional information and official resources.'})).concat(verified.resources.map(d=>({url:d.url,title:d.title,text:d.type+' · Official PDF document'})));const search=()=>{const q=input.value.trim().toLowerCase();const result=q?items.filter(i=>`${i.title} ${i.text}`.toLowerCase().includes(q)):[];document.getElementById('search-status').textContent=q?`${result.length} result${result.length===1?'':'s'} for “${input.value.trim()}”`:'Try “domain”, “classroom”, “annual report” or “network”.';document.getElementById('search-results').innerHTML=result.map(i=>`<a href="${e(i.url)}" ${i.url.startsWith('https')?'target="_blank" rel="noopener noreferrer"':''}><small>${i.url.startsWith('https')?'Official document ↗':e(i.url)}</small><h3>${e(i.title)}</h3><p>${e(i.text)}</p></a>`).join('')|| (q?'<div class="empty"><h3>No results found</h3><p>Try a broader term or explore the <a href="/sitemap">sitemap</a>.</p></div>':'');};form.onsubmit=ev=>{ev.preventDefault();history.replaceState(null,'','/search?q='+encodeURIComponent(input.value));search()};search()}
function bindForm(){const form=document.getElementById('enquiry-form');if(!form)return;form.addEventListener('submit',ev=>{ev.preventDefault();if(!form.reportValidity())return;const d=Object.fromEntries(new FormData(form));const recipient=d.subject.includes('Domain')||d.subject.includes('LMS')?'helpdesk@domain.ernet.in':d.subject==='Web hosting'?'webhosting@ernet.in':d.subject==='eduroam'?'eduroam@ernet.in':'support@eis.ernet.in';const body=`Name: ${d.name}\nEmail: ${d.email}\nInstitution: ${d.organization||'Not specified'}\n\n${d.message}`;const box=document.getElementById('form-status');box.className='form-status';box.innerHTML=`<h3>Your message is ready to review</h3><p>Nothing has been sent. Recipient: ${e(recipient)}</p><pre>${e(body)}</pre><div class="button-row"><a class="button" href="mailto:${recipient}?subject=${encodeURIComponent(d.subject)}&body=${encodeURIComponent(body)}">Open in Email App ${icon('mail')}</a><button class="button secondary" type="button" id="download-draft">Download Draft ${icon('download')}</button></div>`;box.focus();document.getElementById('download-draft').onclick=()=>{const url=URL.createObjectURL(new Blob([`To: ${recipient}\nSubject: ${d.subject}\n\n${body}`],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='ernet-enquiry-draft.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}})}
async function assetCredits(){try{const r=await fetch('/assets/credits.json');const d=await r.json();const rows=Array.isArray(d)?d:d.assets||[];document.getElementById('asset-credits').innerHTML=rows.filter(x=>!x.referenceOnly&&x.publish!==false).map(a=>`<p><strong>${e(a.file||a.filename||a.asset)}</strong> — ${e(a.author||a.credit||'Photograph')} ${a.source?`<a href="${e(a.source)}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:''} ${e(a.license||'')}</p>`).join('')}catch{document.getElementById('asset-credits').innerHTML='<p>Service photography from Unsplash. See the accompanying asset register for individual credits.</p>'}}
render();
